// This code has been fully generated by an AI.

// Package fittest generates synthetic FIT activity files for tests.
//
// Fixtures are synthetic on purpose: the sample files of the Garmin FIT SDK
// must not be redistributed, and personal activities must not be committed.
package fittest

import (
	"bytes"
	"testing"
	"time"

	"github.com/muktihari/fit/encoder"
	"github.com/muktihari/fit/kit/semicircles"
	"github.com/muktihari/fit/profile/filedef"
	"github.com/muktihari/fit/profile/mesgdef"
	"github.com/muktihari/fit/profile/typedef"
)

// Created is the default file creation time (2026-05-01 08:00 UTC).
var Created = time.Date(2026, 5, 1, 8, 0, 0, 0, time.UTC)

// Options describes a synthetic recording. Records start one minute after
// Created, one per second at 8 m/s heading north from 48.2°N 12.8°E.
type Options struct {
	FileType typedef.File
	Serial   uint32
	Created  time.Time
	Points   int
	WithGPS  bool
	Power    bool
	HROffset uint8 // varies record content without touching file_id
	// NoSession simulates a recording aborted before the summary was written.
	NoSession bool
}

// Default returns a 60-second outdoor ride with GPS, heart rate and power.
func Default() Options {
	return Options{FileType: typedef.FileActivity, Serial: 3412345678, Created: Created, Points: 60, WithGPS: true, Power: true}
}

// Encode builds the FIT file described by o.
func Encode(tb testing.TB, o Options) []byte {
	tb.Helper()
	act := filedef.NewActivity()
	act.FileId.
		SetType(o.FileType).
		SetManufacturer(typedef.ManufacturerGarmin).
		SetProduct(4440).
		SetSerialNumber(o.Serial).
		SetTimeCreated(o.Created)

	start := o.Created.Add(time.Minute)
	for i := range o.Points {
		rec := mesgdef.NewRecord(nil).
			SetTimestamp(start.Add(time.Duration(i) * time.Second)).
			SetDistance(uint32(i * 800)). // 8 m/s, scale 100
			SetHeartRate(120 + o.HROffset).
			SetCadence(85).
			SetEnhancedAltitude(uint32((400 + 500) * 5)) // 400 m, scale 5, offset 500
		if o.WithGPS {
			rec.SetPositionLat(semicircles.ToSemicircles(48.2 + float64(i)*1e-4)).
				SetPositionLong(semicircles.ToSemicircles(12.8))
		}
		if o.Power {
			rec.SetPower(210)
		}
		act.Records = append(act.Records, rec)
	}
	end := start.Add(time.Duration(o.Points) * time.Second)
	if !o.NoSession {
		act.Laps = append(act.Laps, mesgdef.NewLap(nil).SetTimestamp(end).SetStartTime(start))
		act.Sessions = append(act.Sessions, mesgdef.NewSession(nil).
			SetTimestamp(end).
			SetStartTime(start).
			SetSport(typedef.SportCycling).
			SetSubSport(typedef.SubSportRoad).
			SetTotalDistance(uint32(o.Points*800)).
			SetTotalTimerTime(uint32(o.Points*1000)).
			SetTotalElapsedTime(uint32(o.Points*1000)).
			SetTotalAscent(12))
		act.Activity = mesgdef.NewActivity(nil).
			SetTimestamp(end).
			SetLocalTimestamp(end.Add(2 * time.Hour)).
			SetNumSessions(1).
			SetType(typedef.ActivityManual)
	}

	fit := act.ToFIT(nil)
	var buf bytes.Buffer
	if err := encoder.New(&buf).Encode(&fit); err != nil {
		tb.Fatalf("encode fixture: %v", err)
	}
	return buf.Bytes()
}
